<?php declare(strict_types=1);define('TP_ROOT',dirname(__DIR__));define('TP_APP',TP_ROOT.'/app');define('TP_VERSION','1.0.0-dev.1');if(!defined('TP_START')){define('TP_START',microtime(true));}spl_autoload_register(static function(string $class):void{if(!str_starts_with($class,'App\\')){return;}$relative=substr($class,4);$file=TP_APP.'/'.str_replace('\\','/',$relative).'.php';if(is_file($file)){require $file;}});require_once TP_APP.'/helpers.php';mb_internal_encoding('UTF-8');date_default_timezone_set('UTC');$configFile=TP_ROOT.'/config/config.php';if(is_file($configFile)){App\Core\Config::load(require $configFile);}else{App\Core\Config::load(require TP_ROOT.'/config/config.example.php');App\Core\Config::set('app.installed',false);}error_reporting(E_ALL);ini_set('display_errors',App\Core\Config::get('app.debug')?'1':'0');ini_set('log_errors','1');ini_set('error_log',TP_ROOT.'/storage/logs/php-error.log');